SELECT mu.id AS employeeId, IF(mu.nick_name IS NULL, mu.user_name, nick_name) as employeeName, mu.user_name as employeeUserName, CASE #{entity.settlementStatus} WHEN '10' THEN ROUND(SUM(msr.adjusted_num - msr.settled_num),4) WHEN '20' THEN 0 END AS totalAdjustedNum, CASE #{entity.settlementStatus} WHEN '10' THEN 0 WHEN '20' THEN SUM(msr.settled_num) END AS totalSettledNum FROM micro_settlement_report msr INNER JOIN micro_user mu ON msr.tenant_code = mu.tenant_code AND msr.employee_id = mu.id WHERE 1=1
and msr.settlement_status = #{entity.settlementStatus}
and msr.employee_id = #{entity.employeeId}
AND DATE_FORMAT(msr.settlement_day,'%y%m') = DATE_FORMAT(#{entity.settlementDay},'%y%m')
and msr.product_seq = #{entity.productSeq} and msr.operate_process_seq = #{entity.operateProcessSeq}
GROUP BY mu.id ORDER BY mu.id

SELECT msr.employee_id AS employeeId, msr.settlement_day AS settlementDay, msr.product_seq AS productSeq, MAX(mp.product_code) AS productCode, MAX(mp.product_name) AS productName, MAX(mp.unit) AS productUnit, msr.operate_process_seq AS operateProcessSeq, MAX(mpc.process_code) AS operateProcessCode, MAX(mpc.process_name) AS operateProcessName, ROUND(SUM(msr.adjusted_num - msr.settled_num), 4) AS adjustedNum, SUM(msr.settled_num) AS settledNum, MAX(msr.remark) AS remark FROM micro_settlement_report msr LEFT JOIN micro_process_common mpc ON msr.tenant_code = mpc.tenant_code AND msr.operate_process_seq = mpc.process_seq LEFT JOIN micro_product mp ON msr.tenant_code = mp.tenant_code AND msr.product_seq = mp.product_seq WHERE msr.employee_id in
#{item}
and msr.settlement_status = #{entity.settlementStatus}
and msr.employee_id = #{entity.employeeId}
AND DATE_FORMAT(msr.settlement_day,'%y%m') = DATE_FORMAT(#{entity.settlementDay},'%y%m')
and msr.product_seq = #{entity.productSeq} and msr.operate_process_seq = #{entity.operateProcessSeq}
GROUP BY msr.employee_id, msr.product_seq,msr.operate_process_seq ORDER BY msr.employee_id, msr.product_seq,msr.operate_process_seq

SELECT msr.product_seq as productSeq, MAX(mp.product_code) AS productCode, MAX(mp.product_name) AS productName, MAX(mp.unit) AS productUnit, SUM(msr.product_complete_num) AS storageNum, COUNT(distinct msr.operate_process_seq) as processNum, COUNT(distinct msr.employee_id) as employeeNum FROM micro_settlement_report msr LEFT JOIN micro_product mp ON msr.product_seq = mp.product_seq AND msr.tenant_code = mp.tenant_code WHERE msr.settlement_status = '20'
and msr.employee_id = #{entity.employeeId}
AND DATE_FORMAT(msr.settlement_day,'%y%m') = DATE_FORMAT(#{entity.settlementDay},'%y%m')
and msr.product_seq = #{entity.productSeq} and msr.operate_process_seq = #{entity.operateProcessSeq}
GROUP BY msr.product_seq ORDER BY msr.product_seq


where
settlement_status = '10'
and product_seq in

    #{item}

and created_date <= #{submitDeadline}
order by product_seq,submit_id

