update micro_settlement_report
tenant_code = #{tenantCode}, submit_id = #{submitId}, employee_id = #{employeeId}, checked_num = #{checkedNum}, settled_num = #{settledNum}, adjusted_num = #{adjustedNum}, settlement_day = #{settlementDay}, product_seq = #{productSeq}, operate_process_seq = #{operateProcessSeq}, product_complete_num = #{productCompleteNum}, product_complete_report_no = #{productCompleteReportNo}, remark = #{remark}, settlement_status = #{settlementStatus}, settlement_no = #{settlementNo}, created_by = #{createdBy}, created_date = #{createdDate}, last_upd_by = #{lastUpdBy}, last_upd_date = #{lastUpdDate},
where id = #{id}
